import re
from datetime import date
from decimal import Decimal, ROUND_HALF_UP


def _clean(value):
    return re.sub(r"\s+", "", str(value))


def _require(data, field):
    if field not in data:
        raise ValueError(f"missing required field: {field}")


def _default(data, field, value):
    if field not in data:
        data[field] = value


def _rename(data, old, new):
    if old in data:
        data[new] = data.pop(old)


def _drop(data, field):
    data.pop(field, None)


def _cents(data, field):
    if field in data:
        amount = Decimal(_clean(data[field])) * 100
        data[field] = int(amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def _bool(data, field):
    if field in data:
        value = _clean(data[field]).lower()
        if value in ("yes", "true", "1"):
            data[field] = True
        elif value in ("no", "false", "0"):
            data[field] = False
        else:
            raise ValueError(f"invalid boolean: {data[field]!r}")


def _iso_date(data, field):
    if field in data:
        value = _clean(data[field])
        match = re.fullmatch(r"(\d{1,2})/(\d{1,2})/(\d{4})", value)
        if not match:
            raise ValueError(f"invalid date: {data[field]!r}")
        day, month, year = map(int, match.groups())
        data[field] = date(year, month, day).isoformat()


def _split(data, field, separator):
    if field in data:
        data[field] = [
            piece.strip()
            for piece in data[field].split(separator)
            if piece.strip()
        ]


def _string_method(method):
    def apply(data, field):
        if field in data:
            data[field] = getattr(data[field], method)()

    return apply


_OPS = {
    "require": _require,
    "default": _default,
    "strip": _string_method("strip"),
    "lower": _string_method("lower"),
    "upper": _string_method("upper"),
    "rename": _rename,
    "drop": _drop,
    "cents": _cents,
    "bool": _bool,
    "iso-date": _iso_date,
    "split": _split,
}


def run(record, rules, base=None):
    data = base(record) if base is not None else dict(record)
    for rule in rules:
        _OPS[rule[0]](data, *rule[1:])
    return data

